class Solution {
public:
    string largestMerge(string word1, string word2) {
        string res;
        int i = 0, j = 0;
        while (i < (int)word1.size() && j < (int)word2.size()) {
            if (word1.compare(i, string::npos, word2, j, string::npos) > 0)
                res.push_back(word1[i++]);
            else
                res.push_back(word2[j++]);
        }
        res += word1.substr(i);
        res += word2.substr(j);
        return res;
    }
};

